mapper.select:
SELECT  FROM APIGRAB_AUTH_CONFIG a

    AND a.name LIKE CONCAT('%', #{name}, '%')
    AND a.auth_type = #{authType}
    AND a.status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.EnableStatusTypeHandler}

ORDER BY a.id DESC

mapper.update:
UPDATE APIGRAB_AUTH_CONFIG
name = #{name}, auth_type = #{authType}, auth_config = #{authConfig, typeHandler=com.gitee.apigrab.persistence.handler.AuthConfigTypeHandler}, status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.EnableStatusTypeHandler}, remark = #{remark},
WHERE id = #{id}
